"""Model-series evaluator: tabulate V2, V3, V4 and their sign-corrected values."""
from __future__ import annotations
import math

def sign_osc(n: int) -> int:
    return 1 if n % 2 == 0 else -1

def is_square(n: int) -> bool:
    r = math.isqrt(n); return r * r == n

def V2(n: int) -> int:
    return sign_osc(n) * (2 ** n + 1) + n

def V3(n: int) -> int:
    return sign_osc(n) * (n - 4) + 2

def V4(n: int) -> int:
    e = -sign_osc(n) * 2 * (n + 1) if is_square(n) else 0
    return sign_osc(n) * (n + 1) + e

def corrected(V, n: int) -> int:
    return sign_osc(n) * V(n)

if __name__ == "__main__":
    for name, V in (("V2", V2), ("V3", V3), ("V4", V4)):
        vals = [corrected(V, n) for n in range(15)]
        print(f"{name}: (-1)^n V(n) for n=0..14 -> {vals}")

"""Empirical vs analytic density of the v4 exceptional set (the perfect squares)."""
from __future__ import annotations
import math

def excCount4(M: int) -> int:
    return sum(1 for n in range(M) if math.isqrt(n) ** 2 == n)

def report(M: int) -> tuple[int, int, float, float]:
    c = excCount4(M)
    s = math.isqrt(M)
    return c, s + 1, c / M, 1 / s + 1 / (s * s)

if __name__ == "__main__":
    print(f"{'M':>9}{'exc':>7}{'bound':>7}{'exc/M':>12}{'1/s+1/s^2':>12}")
    for M in (100, 1000, 10000, 100000, 1000000):
        c, b, d, a = report(M)
        print(f"{M:>9}{c:>7}{b:>7}{d:>12.6f}{a:>12.6f}")

"""Sharpness demo: at |E| = A the boundary series W fails on every odd index."""
from __future__ import annotations

def sign_osc(n: int) -> int:
    return 1 if n % 2 == 0 else -1

def W(n: int) -> int:
    A = n + 1
    if n % 2 == 1:            # critical tuning E(n) = -(-1)^n A(n)
        return sign_osc(n) * A - sign_osc(n) * A
    return sign_osc(n) * A

if __name__ == "__main__":
    fails = [n for n in range(20) if sign_osc(n) * W(n) <= 0]
    print("violation indices in [0,20):", fails)
    print("density of odd numbers (violations):", len(fails) / 20)

