function VERIFY_ALTERNATION(A, E, N, M):
    for n from N to M-1:
        s <- (-1)^n
        corrected <- A(n) + s * E(n)
        if corrected <= 0:
            return FALSE          # domination fails at index n
    return TRUE                   # (-1)^n V(n) > 0 on [N, M)

function EXCEPTIONAL_DENSITY(V, M):
    exc <- 0
    for n from 0 to M-1:
        if (-1)^n * V(n) <= 0:
            exc <- exc + 1
    s <- floor(sqrt(M))
    return (exc / M, (s + 1) / M)

function FIND_THRESHOLD(A, E, search_max, stable_run):
    last_bad <- -1
    for n from 0 to search_max-1:
        if A(n) + (-1)^n * E(n) <= 0:
            last_bad <- n
        else if n - last_bad >= stable_run:
            return last_bad + 1
    return NONE
